161	export const runtime = "nodejs";
162	export const dynamic = "force-dynamic";
163	
164	/**
165	 * DNS lookup — resolves A / AAAA / MX / TXT / NS / CNAME / SOA for a domain via
166	 * node:dns. Public DNS only (no connections are made to the target), but we still
167	 * validate the hostname and cap output. Rate-limited per IP.
168	 */
169	
170	const TIMEOUT_MS = 5000;
171	const TYPES = ["A", "AAAA", "MX", "TXT", "NS", "CNAME", "SOA"] as const;
172	type RecordType = (typeof TYPES)[number];
173	
174	function withTimeout<T>(p: Promise<T>): Promise<T> {
175	  return Promise.race([
176	    p,
177	    new Promise<T>((_, rej) => setTimeout(() => rej(new Error("timeout")), TIMEOUT_MS)),
178	  ]);
179	}
180	
181	export async function POST(req: Request) {
182	  const limited = toolRateLimitByIp(req, "dns", { max: 30, windowMs: 60_000 });
183	  if (limited) return limited;
184	
185	  const raw = await readField(req, "domain");
186	  const host = extractHost(raw);
187	  if (!host || !isPlausibleHost(host)) return jsonError("Enter a valid domain name.");
188	  if (host === "localhost") return jsonError("That host is not allowed.");
189	
190	  const resolver = new Resolver({ timeout: TIMEOUT_MS, tries: 2 });
191	
192	  async function resolveType(type: RecordType): Promise<string[]> {
193	    try {
194	      switch (type) {
195	        case "A":
196	          return await withTimeout(resolver.resolve4(host!));
197	        case "AAAA":
198	          return await withTimeout(resolver.resolve6(host!));
199	        case "MX": {
200	          const mx = await withTimeout(resolver.resolveMx(host!));
201	          return mx
202	            .sort((a, b) => a.priority - b.priority)
203	            .map((r) => `${r.priority}\t${r.exchange}`);
204	        }
205	        case "TXT": {
206	          const txt = await withTimeout(resolver.resolveTxt(host!));
207	          return txt.map((chunks) => chunks.join(""));
208	        }
209	        case "NS":
210	          return await withTimeout(resolver.resolveNs(host!));
211	        case "CNAME":
212	          return await withTimeout(resolver.resolveCname(host!));
213	        case "SOA": {
214	          const soa = await withTimeout(resolver.resolveSoa(host!));
215	          return [
216	            `${soa.nsname} ${soa.hostmaster} serial=${soa.serial} refresh=${soa.refresh} retry=${soa.retry} expire=${soa.expire} minttl=${soa.minttl}`,
217	          ];
218	        }
219	      }
220	    } catch {
221	      return [];
222	    }
223	  }
224	
225	  try {
226	    const settled = await Promise.all(
227	      TYPES.map(async (t) => [t, (await resolveType(t)).slice(0, 100)] as const),
228	    );
229	    const records: Record<string, string[]> = {};
230	    for (const [t, vals] of settled) records[t] = vals;
231	    const total = Object.values(records).reduce((n, v) => n + v.length, 0);
232	    if (total === 0) return jsonError("No DNS records found (the domain may not exist).", 404);
233	    return NextResponse.json({ ok: true, host, records });
234	  } catch {
235	    return jsonError("DNS lookup failed.", 502);
236	  }
237	}
