270	import { NextResponse } from "next/server";
271	import net from "node:net";
272	import { jsonError } from "@/lib/tools/api";
273	import { toolRateLimitByIp, trustedClientIp } from "@/app/api/_lib/client-ip";
274	import { checkRateLimit } from "@/lib/rate-limit";
275	import { extractHost, resolvePublicHost, BlockedHostError } from "@/lib/tools/net-guard";
276	
277	export const runtime = "nodejs";
278	export const dynamic = "force-dynamic";
279	
280	/**
281	 * TCP port checker — opens a TCP connection to host:port and reports open/closed
282	 * plus connect latency. The host is SSRF-guarded (resolved to a public IP; private
283	 * / loopback / reserved targets are rejected) and we connect to the vetted IP,
284	 * never re-resolving. Port must be 1-65535. Timeout ≤5s, rate-limited per IP.
285	 */
286	
287	const TIMEOUT_MS = 5000;
288	
289	const COMMON: Record<number, string> = {
290	  20: "FTP-DATA", 21: "FTP", 22: "SSH", 23: "Telnet", 25: "SMTP", 53: "DNS",
291	  80: "HTTP", 110: "POP3", 143: "IMAP", 443: "HTTPS", 465: "SMTPS", 587: "SMTP",
292	  993: "IMAPS", 995: "POP3S", 3306: "MySQL", 3389: "RDP", 5432: "PostgreSQL",
293	  6379: "Redis", 8080: "HTTP-alt", 8443: "HTTPS-alt", 27017: "MongoDB",
294	};
295	
296	function tryConnect(ip: string, port: number): Promise<{ open: boolean; latencyMs: number }> {
297	  return new Promise((resolve) => {
298	    const started = Date.now();
299	    const socket = new net.Socket();
300	    let settled = false;
301	    const finish = (open: boolean) => {
302	      if (settled) return;
303	      settled = true;
304	      socket.destroy();
305	      resolve({ open, latencyMs: Date.now() - started });
306	    };
307	    socket.setTimeout(TIMEOUT_MS);
308	    socket.once("connect", () => finish(true));
309	    socket.once("timeout", () => finish(false));
310	    socket.once("error", () => finish(false));
311	    socket.connect(port, ip);
312	  });
313	}
314	
315	export async function POST(req: Request) {
316	  const limited = toolRateLimitByIp(req, "port", { max: 20, windowMs: 60_000 });
317	  if (limited) return limited;
318	
319	  const body = (await req.json().catch(() => ({}))) as { host?: unknown; port?: unknown };
320	  const host = extractHost(typeof body.host === "string" ? body.host : "");
321	  const port = Number(body.port);
322	
323	  if (!host) return jsonError("Enter a valid host.");
324	  if (!Number.isInteger(port) || port < 1 || port > 65535) {
325	    return jsonError("Port must be an integer between 1 and 65535.");
326	  }
327	
328	  try {
329	    const { host: resolved, addresses } = await resolvePublicHost(host);
330	    const ip = addresses[0];
331	    // Extra per-target throttle so we can't be used to sweep one host's ports.
332	    const sweep = checkRateLimit(`portsweep:${trustedClientIp(req)}:${resolved}`, {
333	      max: 30,
334	      windowMs: 60_000,
335	    });
336	    if (!sweep.ok) return jsonError(`Too many checks against that host. Try again in ${sweep.retryAfterSec}s.`, 429);
337	
338	    const result = await tryConnect(ip, port);
339	    return NextResponse.json({
340	      ok: true,
341	      host: resolved,
342	      ip,
343	      port,
344	      service: COMMON[port] ?? null,
345	      open: result.open,
346	      latencyMs: result.open ? result.latencyMs : null,
347	    });
348	  } catch (e) {
349	    if (e instanceof BlockedHostError) return jsonError(e.message, 403);
350	    return jsonError("Port check failed.", 502);
351	  }
352	}
