494	/**
495	 * HTTP header inspector — fetches a URL and returns the status + response headers.
496	 *
497	 * SSRF guard, in layers:
498	 *   1. Only http/https schemes.
499	 *   2. `resolvePublicHost` resolves the host and rejects if ANY resolved address
500	 *      is private / loopback / link-local / reserved.
501	 *   3. The connection is PINNED to an address vetted in step 2 (see
502	 *      `pinnedAgent`), so the name is never resolved a second time.
503	 *   4. Redirects are NOT followed (`redirect: "manual"`) — we only report the
504	 *      Location header, so we can't be bounced to an internal endpoint.
505	 *   5. 5s timeout, header values capped, the body is never read.
506	 *
507	 * Step 3 used to be missing, and steps 2 and 4 do not cover the gap it left.
508	 * `resolvePublicHost(url.hostname)` was called for its throw-or-don't side
509	 * effect and its returned `addresses` were discarded; the fetch that followed
510	 * was handed the HOSTNAME, so the runtime resolved it AGAIN on the way out.
511	 * That is a textbook DNS-rebinding window: an attacker points a name they
512	 * control at a public IP with a 0-second TTL, we check it and approve it, and
513	 * by the time undici opens the socket the same name answers 127.0.0.1. The
514	 * request then leaves from inside the trust boundary — Proxmox on
515	 * 127.0.0.1:8006, the app itself on :3000, anything on the 10.20.0.0/24 VM
516	 * bridge — and we hand the caller back its status line and every response
517	 * header. `resolvePublicHost` returns `addresses` precisely so callers can
518	 * close this; port-checker and ssl-checker already did, this route did not.
519	 */
520	
521	const TIMEOUT_MS = 5000;
522	
523	/**
524	 * An undici Agent whose DNS resolution is hard-wired to an already-vetted
525	 * address. Host and SNI still come from the URL, so virtual hosts and TLS
526	 * certificate validation behave normally — only the address we dial is fixed.
527	 *
528	 * undici's connector calls `lookup` with `{ all: true }` and expects an ARRAY of
529	 * `{ address, family }`; node's plain `net.connect` contract is the positional
530	 * `(err, address, family)` form. Getting this wrong does not fail the build, it
531	 * fails every request at runtime with "Invalid IP address: undefined" — which is
532	 * how the first cut of this fix was caught — so both shapes are answered here.
533	 */
534	type LookupCallback = (err: Error | null, addresses: unknown, family?: number) => void;
535	
536	function pinnedAgent(address: string): Agent {
537	  const family = net.isIP(address);
538	  return new Agent({
539	    connect: {
540	      lookup: (_hostname: string, options: { all?: boolean }, callback: LookupCallback) => {
541	        if (options?.all) callback(null, [{ address, family }]);
542	        else callback(null, address, family);
543	      },
544	    } as never,
545	  });
546	}
