588	    try {
589	      await res.body?.cancel();
590	    } catch {
591	      /* ignore */
592	    }
593	
594	    const redirected = res.status >= 300 && res.status < 400;
595	    return NextResponse.json(
596	      {
597	        ok: true,
598	        url: url.toString(),
599	        finalHost: url.hostname,
600	        status: res.status,
601	        statusText: res.statusText,
602	        redirect: redirected ? res.headers.get("location") : null,
603	        headers: headers.slice(0, 80),
604	      },
605	      { headers: { "Cache-Control": "private, no-store" } },
