635	const PORT = 43;
636	const TIMEOUT_MS = 5000;
637	const MAX_BYTES = 64 * 1024;
638	
639	/** One raw WHOIS query to `server:43` for `query`. Resolves with the text body. */
640	function whoisQuery(server: string, query: string): Promise<string> {
641	  return new Promise((resolve, reject) => {
642	    const chunks: Buffer[] = [];
643	    let size = 0;
644	    const socket = net.createConnection({ host: server, port: PORT });
645	    socket.setTimeout(TIMEOUT_MS);
646	
647	    const done = (err?: Error) => {
648	      socket.destroy();
649	      if (err) reject(err);
650	      else resolve(Buffer.concat(chunks).toString("utf8"));
651	    };
652	
653	    socket.on("connect", () => socket.write(`${query}\r\n`));
654	    socket.on("data", (d) => {
655	      size += d.length;
656	      if (size > MAX_BYTES) {
657	        chunks.push(d.subarray(0, Math.max(0, MAX_BYTES - (size - d.length))));
658	        done();
659	        return;
660	      }
661	      chunks.push(d);
662	    });
663	    socket.on("end", () => done());
664	    socket.on("timeout", () => done(new Error("WHOIS server timed out.")));
665	    socket.on("error", (e) => done(e));
666	  });
667	}
