676	function summarize(text: string) {
677	  const grab = (labels: string[]): string[] => {
678	    const out: string[] = [];
679	    for (const line of text.split(/\r?\n/)) {
680	      const m = line.match(/^\s*([^:]+):\s*(.+?)\s*$/);
681	      if (!m) continue;
682	      const key = m[1].trim().toLowerCase();
683	      if (labels.some((l) => key === l || key.startsWith(l))) out.push(m[2].trim());
684	    }
685	    return [...new Set(out)];
686	  };
687	  return {
688	    registrar: grab(["registrar", "sponsoring registrar"])[0] ?? null,
689	    created: grab(["creation date", "created", "registered on", "registration time"])[0] ?? null,
690	    updated: grab(["updated date", "last updated", "last modified"])[0] ?? null,
691	    expires: grab(["registry expiry date", "expiration date", "expiry date", "expires", "expire"])[0] ?? null,
692	    status: grab(["domain status", "status"]).slice(0, 6),
693	    nameservers: grab(["name server", "nserver", "nameserver"]).map((n) => n.toLowerCase()).slice(0, 8),
694	  };
695	}
