707	    return jsonError("Enter a fully-qualified domain name.");
708	  }
709	
710	  try {
711	    // 1) Ask IANA which server is authoritative for this TLD.
712	    const ianaText = await whoisQuery("whois.iana.org", host);
713	    const referral = parseReferral(ianaText);
714	
715	    let text = ianaText;
716	    let server = "whois.iana.org";
