753	/**
754	 * "What's my IP" — echoes the caller's public IP plus a reverse-DNS (PTR)
755	 * lookup and a couple of request hints. No user input, so no SSRF surface.
756	 * Handy from a browser or `curl`.
757	 *
758	 * The address comes from `trustedClientIp` (proxy-attested), NOT the first hop
759	 * of `X-Forwarded-For`: nginx APPENDS to that header, so its first entry is
760	 * whatever the caller sent. Keying on it made this tool report an address the
761	 * caller chose — `curl -H 'X-Forwarded-For: 203.0.113.77' …/api/tools/my-ip`
762	 * answered `203.0.113.77`, which is worse than useless for a diagnostic tool.
763	 * `forwardedFor` below still echoes the raw header verbatim so a customer
764	 * debugging their own proxy chain can see it; that is their own input, not ours.
765	 */
766	
767	export async function GET(req: Request) {
768	  const ip = trustedClientIp(req);
769	  const kind = net.isIP(ip);
770	
771	  let ptr: string | null = null;
772	  if (kind !== 0) {
773	    try {
774	      const names = await Promise.race([
775	        reverse(ip),
776	        new Promise<string[]>((_, rej) => setTimeout(() => rej(new Error("timeout")), 3000)),
777	      ]);
778	      ptr = names[0] ?? null;
779	    } catch {
780	      ptr = null;
781	    }
782	  }
783	
784	  return NextResponse.json(
785	    {
786	      ok: true,
787	      ip,
788	      version: kind === 4 ? "IPv4" : kind === 6 ? "IPv6" : "unknown",
789	      reverseDns: ptr,
790	      userAgent: (req.headers.get("user-agent") ?? "").slice(0, 400) || null,
791	      forwardedFor: req.headers.get("x-forwarded-for") ?? null,
792	    },
793	    {
794	      // The response is a description of THIS caller. It carries no explicit
795	      // freshness information otherwise, which lets a shared proxy apply
796	      // heuristic caching (RFC 9111 §4.2.2) and hand one visitor's IP, PTR and
797	      // User-Agent to the next. Pin it to the caller.
798	      headers: { "Cache-Control": "private, no-store" },
799	    },
800	  );
801	}
