838	  let v = value >>> 0;
839	  for (;;) {
840	    if ((v & ~0x7f) === 0) {
841	      bytes.push(v);
842	      break;
843	    }
844	    bytes.push((v & 0x7f) | 0x80);
845	    v >>>= 7;
846	  }
847	  return Buffer.from(bytes);
