853	  let result = 0;
854	  let byte: number;
855	  do {
856	    if (offset + numRead >= buf.length) return null; // incomplete
857	    byte = buf[offset + numRead];
858	    result |= (byte & 0x7f) << (7 * numRead);
859	    numRead++;
860	    if (numRead > 5) return { value: result >>> 0, size: numRead }; // malformed, bail
