import { NextRequest, NextResponse } from "next/server";
import { promises as fs } from "node:fs";
import { join } from "node:path";
import { randomBytes } from "node:crypto";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { BOARD_UPLOAD_DIR } from "@/lib/board-shared";

// Videos can be large; everything else is capped tighter.
const MAX_VIDEO = 300 * 1024 * 1024;
const MAX_OTHER = 50 * 1024 * 1024;

function kindFor(mime: string): "IMAGE" | "VIDEO" | "FILE" {
  if (mime.startsWith("image/")) return "IMAGE";
  if (mime.startsWith("video/")) return "VIDEO";
  return "FILE";
}

/** Upload an attachment to a card. Admin only. Stored on disk so it can be read
 *  and acted on directly. `?cardId=` in the query. */
export async function POST(req: NextRequest) {
  try {
    await requireAdmin();
  } catch {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }
  const cardId = req.nextUrl.searchParams.get("cardId") ?? "";
  const card = await db.card.findUnique({ where: { id: cardId }, select: { id: true } });
  if (!card) return NextResponse.json({ error: "Card not found" }, { status: 404 });

  const form = await req.formData();
  const file = form.get("file");
  if (!(file instanceof File)) return NextResponse.json({ error: "No file" }, { status: 400 });

  const mime = file.type || "application/octet-stream";
  const kind = kindFor(mime);
  const cap = kind === "VIDEO" ? MAX_VIDEO : MAX_OTHER;
  if (file.size > cap) return NextResponse.json({ error: `File too large (max ${Math.round(cap / 1024 / 1024)} MB)` }, { status: 413 });

  const ext = (file.name.match(/\.[A-Za-z0-9]{1,8}$/)?.[0] ?? "").toLowerCase();
  const storedName = `${randomBytes(12).toString("hex")}${ext}`;
  const dir = join(BOARD_UPLOAD_DIR, "board", cardId);
  try {
    await fs.mkdir(dir, { recursive: true });
    await fs.writeFile(join(dir, storedName), Buffer.from(await file.arrayBuffer()));
  } catch (e) {
    // Almost always a permissions problem on BOARD_UPLOAD_DIR (the web process
    // couldn't create/write it — /opt/nxeon is root-owned, the app runs as nxeon).
    // Surface it instead of throwing an opaque 500 the client would swallow — that
    // was exactly the "upload does nothing, no preview" bug.
    console.error("[board] attachment write failed:", e);
    return NextResponse.json(
      { error: `Couldn't save the file (${(e as NodeJS.ErrnoException)?.code ?? "write error"}). Ensure ${BOARD_UPLOAD_DIR} is writable by the web user.` },
      { status: 500 },
    );
  }

  const att = await db.cardAttachment.create({
    data: { cardId, filename: file.name.slice(0, 200), storedName, mime, sizeBytes: file.size, kind },
  });
  return NextResponse.json({ id: att.id, filename: att.filename, kind, mime, sizeBytes: att.sizeBytes, url: `/api/board/attachments/${att.id}` });
}
