import { NextRequest, NextResponse } from "next/server";
import { createReadStream } from "node:fs";
import { promises as fs } from "node:fs";
import { join } from "node:path";
import { Readable } from "node:stream";
import { requireAdmin } from "@/lib/auth";
import { db } from "@/lib/db";
import { BOARD_UPLOAD_DIR } from "@/lib/board-shared";

/** Stream a board attachment. Admin only. Supports Range so video seeks work. */
export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  try {
    await requireAdmin();
  } catch {
    return new NextResponse("Forbidden", { status: 403 });
  }
  const { id } = await params;
  const att = await db.cardAttachment.findUnique({ where: { id } });
  if (!att) return new NextResponse("Not found", { status: 404 });
  const path = join(BOARD_UPLOAD_DIR, "board", att.cardId, att.storedName);
  let size: number;
  try {
    size = (await fs.stat(path)).size;
  } catch {
    return new NextResponse("Missing", { status: 404 });
  }

  const range = req.headers.get("range");
  const disposition = att.kind === "FILE" ? `attachment; filename="${att.filename.replace(/"/g, "")}"` : "inline";
  const baseHeaders: Record<string, string> = { "Content-Type": att.mime, "Content-Disposition": disposition, "Accept-Ranges": "bytes" };

  if (range) {
    const m = /bytes=(\d+)-(\d*)/.exec(range);
    if (m) {
      const start = Number(m[1]);
      const end = m[2] ? Math.min(Number(m[2]), size - 1) : size - 1;
      if (start <= end && start < size) {
        const stream = createReadStream(path, { start, end });
        return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
          status: 206,
          headers: { ...baseHeaders, "Content-Range": `bytes ${start}-${end}/${size}`, "Content-Length": String(end - start + 1) },
        });
      }
    }
  }
  const stream = createReadStream(path);
  return new NextResponse(Readable.toWeb(stream) as unknown as ReadableStream, {
    status: 200,
    headers: { ...baseHeaders, "Content-Length": String(size) },
  });
}
