import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { validateImageBytes, MAX_ATTACHMENT_BYTES } from "@/lib/chat-attachment";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";

/**
 * Image upload for <ChatWidget/>.
 *
 * POST /api/chat/upload  (multipart/form-data: visitorId, file, optional body,
 * optional name/email) — attaches an image to the visitor's OPEN conversation
 * (created if none), exactly like POST /api/chat but carrying an image.
 *
 * Authorization mirrors POST /api/chat: the conversation is scoped strictly by
 * the client-supplied `visitorId`, so a visitor can only ever attach to their
 * own thread. The image is validated by signature (not the client-declared
 * type) in lib/chat-attachment — SVG and non-images are rejected. Bytes live in
 * Postgres. Per-IP rate limited.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

export async function POST(req: Request) {
  const rl = checkRateLimit(`chat-upload:${trustedClientIp(req)}`, { max: 15, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "Too many uploads. Please slow down." },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "Invalid upload." }, { status: 400 });
  }

  const visitorId = clip(form.get("visitorId"), 100);
  const body = clip(form.get("body"), 5000) ?? "";
  const name = clip(form.get("name"), 120);
  const email = clip(form.get("email"), 200);
  const file = form.get("file");

  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
  if (!(file instanceof File)) return NextResponse.json({ error: "No image provided." }, { status: 400 });
  // Cheap guard before buffering the whole body into memory.
  if (file.size > MAX_ATTACHMENT_BYTES) {
    return NextResponse.json({ error: "Image is larger than 5 MB." }, { status: 413 });
  }

  const bytes = Buffer.from(await file.arrayBuffer());
  const check = validateImageBytes(bytes, file.type);
  if (!check.ok) return NextResponse.json({ error: check.error }, { status: 400 });

  const user = await currentUser();

  // Continue the visitor's existing open conversation, else start a new one.
  let convo = await db.chatConversation.findFirst({
    where: { visitorId, status: "OPEN" },
    orderBy: { lastMessageAt: "desc" },
    select: { id: true, name: true, email: true },
  });

  if (!convo) {
    convo = await db.chatConversation.create({
      data: {
        visitorId,
        userId: user?.id ?? null,
        name: name ?? user?.name ?? null,
        email: email ?? user?.email ?? null,
      },
      select: { id: true, name: true, email: true },
    });
  }

  const convoId = convo.id;
  await db.$transaction(async (tx) => {
    const msg = await tx.chatMessage.create({
      data: { conversationId: convoId, sender: "visitor", body },
    });
    await tx.chatAttachment.create({
      data: {
        messageId: msg.id,
        mime: check.mime,
        sizeBytes: check.bytes.length,
        data: new Uint8Array(check.bytes),
      },
    });
    await tx.chatConversation.update({
      where: { id: convoId },
      data: {
        unreadForAgent: true,
        lastMessageAt: new Date(),
        ...(user?.id ? { userId: user.id } : {}),
        ...(name && !convo!.name ? { name } : {}),
        ...(email && !convo!.email ? { email } : {}),
      },
    });
  });

  const full = await db.chatConversation.findUnique({
    where: { id: convoId },
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });

  return NextResponse.json(
    {
      conversation: full
        ? { id: full.id, status: full.status, name: full.name, email: full.email }
        : null,
      messages: (full?.messages ?? []).map((m) => ({
        id: m.id,
        sender: m.sender,
        body: m.body,
        createdAt: m.createdAt.toISOString(),
        attachment: m.attachment
          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
          : null,
      })),
    },
    { headers: NO_STORE_HEADERS },
  );
}
