import { db } from "@/lib/db";
import { realUser, currentUser } from "@/lib/auth";
import { isStaff } from "@/lib/rbac";
import { isAllowedImageMime } from "@/lib/chat-attachment";

export const runtime = "nodejs";

/**
 * GET /api/chat/attachment/[id]?visitorId=…  — stream a chat image ONLY to an
 * authorized viewer:
 *   • any staff member (SUPPORT / ADMIN), OR
 *   • the visitor who owns the conversation (visitorId query param matches), OR
 *   • the signed-in customer the conversation is linked to (userId matches).
 *
 * `id` is a database id, never a filename, so there is no path traversal. The
 * response is locked down: the real stored MIME (always an allow-listed image),
 * `nosniff`, an inline disposition with a fixed filename, and a `default-src
 * 'none'` CSP so it can never execute as a document even if a browser is coaxed
 * into treating it as one.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

export async function GET(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  if (typeof id !== "string" || !id) return new Response("Not found", { status: 404 });

  const attachment = await db.chatAttachment.findUnique({
    where: { id },
    include: { message: { include: { conversation: true } } },
  });
  if (!attachment) return new Response("Not found", { status: 404 });

  const convo = attachment.message.conversation;

  // --- Authorization: same model as upload (participant or staff) ---
  let authorized = false;

  const staff = await realUser();
  if (staff && isStaff(staff.role)) {
    authorized = true;
  } else {
    const url = new URL(req.url);
    const visitorId = clip(url.searchParams.get("visitorId"), 100);
    if (visitorId && visitorId === convo.visitorId) {
      authorized = true;
    } else if (convo.userId) {
      const user = await currentUser();
      if (user && user.id === convo.userId) authorized = true;
    }
  }

  if (!authorized) return new Response("Forbidden", { status: 403 });

  // Defense in depth: never serve anything that isn't an allow-listed image.
  const mime = isAllowedImageMime(attachment.mime) ? attachment.mime : "application/octet-stream";

  const data: Buffer = Buffer.isBuffer(attachment.data)
    ? attachment.data
    : Buffer.from(attachment.data as Uint8Array);

  return new Response(new Uint8Array(data), {
    status: 200,
    headers: {
      "Content-Type": mime,
      "Content-Length": String(data.length),
      "Content-Disposition": 'inline; filename="image"',
      "X-Content-Type-Options": "nosniff",
      "Content-Security-Policy": "default-src 'none'; sandbox",
      "Cache-Control": "private, max-age=86400, no-transform",
    },
  });
}

