import { db } from "@/lib/db";
import { isAllowedImageMime } from "@/lib/chat-attachment";

export const runtime = "nodejs";

/**
 * GET /api/mail/signature-image/[id] — serve a stored signature image.
 *
 * PUBLIC BY DESIGN: this URL is embedded as an <img src> inside outgoing email
 * signatures, so it is loaded by RECIPIENTS in external inboxes (Gmail image
 * proxy, Outlook, Apple Mail) that have no Nxeon session. There is therefore no
 * auth here. The exposure is limited: `id` is an unguessable cuid (never a
 * filename, so no path traversal), and the response only ever returns stored
 * image bytes with an allow-listed image Content-Type — never HTML/JS, and a
 * `default-src 'none'; sandbox` CSP + nosniff prevent it executing as a document.
 *
 * Cached aggressively (immutable, 1 year) since a given id's bytes never change.
 */

export async function GET(
  _req: Request,
  { params }: { params: Promise<{ id: string }> },
) {
  const { id } = await params;
  if (typeof id !== "string" || !id) return new Response("Not found", { status: 404 });

  const image = await db.signatureImage.findUnique({
    where: { id },
    select: { mime: true, data: true },
  });
  if (!image) return new Response("Not found", { status: 404 });

  // Defense in depth: never serve anything that isn't an allow-listed image.
  const mime = isAllowedImageMime(image.mime) ? image.mime : "application/octet-stream";

  const data: Buffer = Buffer.isBuffer(image.data)
    ? image.data
    : Buffer.from(image.data as Uint8Array);

  return new Response(new Uint8Array(data), {
    status: 200,
    headers: {
      "Content-Type": mime,
      "Content-Length": String(data.length),
      "Content-Disposition": 'inline; filename="image"',
      "X-Content-Type-Options": "nosniff",
      "Content-Security-Policy": "default-src 'none'; sandbox",
      "Cache-Control": "public, max-age=31536000, immutable",
    },
  });
}
