import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import {
  readFileBuffer,
  writeFileBuffer,
  mkdirPath,
  normalizePath,
  validateName,
  joinPath,
  type SftpServer,
} from "@/lib/sftp";

/**
 * File download / upload endpoint for the in-portal file manager.
 *
 *   GET  /api/files/[serverId]?path=/abs/file&download=1   -> streams the file
 *   POST /api/files/[serverId]?path=/abs/dir               -> multipart upload
 *
 * Both are authenticated and ownership-checked (owner or admin), path-validated
 * (absolute, no `..`), size-capped, and rate-limited. Real SFTP in production;
 * an in-memory simulation on the sandbox (handled inside lib/sftp).
 */
export const dynamic = "force-dynamic";

/** Max upload size accepted per request. */
const MAX_UPLOAD_BYTES = 100 * 1024 * 1024; // 100 MB

async function ownedServer(
  serverId: string,
  userId: string,
  isAdmin: boolean
): Promise<SftpServer | null> {
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: {
      id: true,
      userId: true,
      rootPassword: true,
      // The encrypted-at-rest password is the authoritative one for any server
      // provisioned after credential encryption shipped; the plaintext column is
      // null for those. serverRootPassword() prefers Enc and falls back to
      // plaintext, so BOTH must be selected — omitting Enc made every
      // encrypted-password server fail with "Server has no root password set."
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!server) return null;
  if (server.userId !== userId && !isAdmin) return null;
  return server;
}

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ serverId: string }> }
) {
  const { serverId } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const rl = checkRateLimit(`files:download:${user.id}`, { max: 60, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "too many downloads — slow down", retryAfterSec: rl.retryAfterSec },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });

  let path: string;
  try {
    path = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "invalid path" },
      { status: 400 }
    );
  }
  if (path === "/") return NextResponse.json({ error: "not a file" }, { status: 400 });

  let data: Buffer;
  try {
    data = await readFileBuffer(server, path);
  } catch (err) {
    const msg = err instanceof Error ? err.message : "read failed";
    const status = /No such|Not a file/i.test(msg) ? 404 : 502;
    return NextResponse.json({ error: msg }, { status });
  }

  const filename = path.split("/").pop() || "download";
  // Always force a download to avoid the browser rendering server content inline.
  return new NextResponse(data as unknown as BodyInit, {
    status: 200,
    headers: {
      "Content-Type": "application/octet-stream",
      "Content-Length": String(data.length),
      "Content-Disposition": `attachment; filename="${filename.replace(/["\\]/g, "_")}"`,
      "Cache-Control": "private, no-store",
    },
  });
}

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ serverId: string }> }
) {
  const { serverId } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const rl = checkRateLimit(`files:upload:${user.id}`, { max: 30, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "too many uploads — slow down", retryAfterSec: rl.retryAfterSec },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  const server = await ownedServer(serverId, user.id, user.role === "ADMIN");
  if (!server) return NextResponse.json({ error: "not found" }, { status: 404 });

  let dir: string;
  try {
    dir = normalizePath(req.nextUrl.searchParams.get("path") ?? "");
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "invalid path" },
      { status: 400 }
    );
  }

  let form: FormData;
  try {
    form = await req.formData();
  } catch {
    return NextResponse.json({ error: "expected a multipart upload" }, { status: 400 });
  }

  const file = form.get("file");
  if (!(file instanceof File)) {
    return NextResponse.json({ error: "no file provided" }, { status: 400 });
  }
  if (file.size > MAX_UPLOAD_BYTES) {
    return NextResponse.json(
      { error: `file exceeds the ${MAX_UPLOAD_BYTES / (1024 * 1024)} MB upload limit` },
      { status: 413 }
    );
  }

  let target: string;
  try {
    const name = validateName((file.name || "upload").trim());
    target = joinPath(dir, name);
  } catch (err) {
    return NextResponse.json(
      { error: err instanceof Error ? err.message : "invalid filename" },
      { status: 400 }
    );
  }

  try {
    const data = Buffer.from(await file.arrayBuffer());
    // Re-check the actual byte length in case the reported size was understated.
    if (data.length > MAX_UPLOAD_BYTES) {
      return NextResponse.json({ error: "file too large" }, { status: 413 });
    }
    // Best-effort: create the destination directory. The file manager always
    // targets an existing dir (mkdir throws "already exists" → ignored), but the
    // Matrix console uploads into ~/nxeon-uploads, which may not exist yet, and
    // client.put() does not create parent dirs. Harmless when it already exists.
    try {
      await mkdirPath(server, dir);
    } catch {
      /* already exists / benign — the write below surfaces any real failure */
    }
    await writeFileBuffer(server, target, data);
  } catch (err) {
    const msg = err instanceof Error ? err.message : "upload failed";
    const status = /Invalid|directory/i.test(msg) ? 400 : 502;
    return NextResponse.json({ error: msg }, { status });
  }

  return NextResponse.json({ ok: true, path: target });
}
