import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";

/**
 * GET /api/chat/[id]?visitorId=…  — fetch a single conversation the widget
 * already knows the id of. Strictly scoped: the row is only returned when its
 * `visitorId` matches the one supplied, so a visitor can never read another's
 * thread by guessing an id. Reading clears the visitor-facing unread flag.
 */

function clip(v: unknown, max: number): string | null {
  return typeof v === "string" && v.trim() ? v.trim().slice(0, max) : null;
}

export async function GET(
  req: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;
  const url = new URL(req.url);
  const visitorId = clip(url.searchParams.get("visitorId"), 100);

  if (!id || !visitorId) {
    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
  }

  const convo = await db.chatConversation.findFirst({
    where: { id, visitorId },
    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
  });

  if (!convo) {
    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
  }

  if (convo.unreadForUser) {
    await db.chatConversation
      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
      .catch(() => {});
  }

  return NextResponse.json(
    {
      conversation: {
        id: convo.id,
        status: convo.status,
        name: convo.name,
        email: convo.email,
      },
      messages: convo.messages.map((m) => ({
        id: m.id,
        sender: m.sender,
        body: m.body,
        createdAt: m.createdAt.toISOString(),
        attachment: m.attachment
          ? { id: m.attachment.id, mime: m.attachment.mime, sizeBytes: m.attachment.sizeBytes }
          : null,
      })),
    },
    { headers: NO_STORE_HEADERS },
  );
}

