/**
 * Sitewave — PHASE 2 SSRF-SAFE scrape + extract.
 *
 * OPERATOR-TRIGGERED ONLY. This module is never called by a crawler or on a
 * schedule — it runs exactly once when an operator clicks "Scrape & generate" on
 * a prospect whose currentSiteUrl they have chosen to fetch. It reads a SINGLE
 * public page and pulls light brand signals (business name, tagline, headings,
 * services, contact, a colour hint) with NO headless browser — plain fetch +
 * regex. The extracted text is fed to generateSiteIR to improve the demo; the
 * generator still degrades to the deterministic fallback without ANTHROPIC_API_KEY.
 *
 * SECURITY (the whole point of this file). A URL an operator pastes is untrusted
 * and could point at our own infrastructure — cloud metadata, localhost admin
 * ports, RFC-1918 hosts. Every hop is validated BEFORE we connect:
 *   - https/http only (no file:, gopher:, data:, ftp: …);
 *   - the hostname is DNS-resolved and EVERY resolved address must be a public,
 *     routable unicast IP — loopback / private / link-local / CGNAT / metadata /
 *     multicast / reserved / IPv4-mapped-IPv6 are all refused;
 *   - redirects are followed manually, at most MAX_REDIRECTS, and the Location of
 *     each hop is re-parsed and re-validated the same way (defeats a public host
 *     that 302s to 169.254.169.254);
 *   - the response is capped at MAX_BYTES and the whole request at TIMEOUT_MS;
 *   - a descriptive, honest User-Agent is sent.
 *
 * The IP-guard helpers are pure + exported so the refusal logic is unit-tested.
 */

import { isIP } from "node:net";
import { lookup } from "node:dns/promises";

// --- caps -------------------------------------------------------------------

export const MAX_BYTES = 2_000_000; // ~2 MB
export const TIMEOUT_MS = 10_000; // ~10 s wall clock for the whole fetch
export const MAX_REDIRECTS = 3;
export const USER_AGENT =
  "SitewaveBot/1.0 (+concept-redesign; operator-triggered; respects robots)";

