import { db } from "@/lib/db";
import { realUser } from "@/lib/auth";
import { isStaff, canAccess } from "@/lib/rbac";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Serve a generated Sitewave demo's stored HTML for PREVIEW.
 *
 * GET /api/agency/demo/<id>/preview — returns the deterministically rendered,
 * self-contained HTML of the demo (admin/platform staff only). The response
 * carries `X-Robots-Tag: noindex, nofollow` on top of the `<meta robots>` the
 * renderer already bakes in, so a previewed demo can never be indexed. This is a
 * read-only preview surface — it renders stored bytes and provisions nothing.
 */
export async function GET(_req: Request, ctx: { params: Promise<{ id: string }> }) {
  const user = await realUser();
  if (!user || !isStaff(user.role) || !canAccess(user.role, "platform")) {
    return new Response("Not found", { status: 404 });
  }

  const { id } = await ctx.params;
  const demo = await db.agencyDemoSite.findUnique({
    where: { id },
    select: { renderedHtml: true },
  });
  if (!demo || !demo.renderedHtml) {
    return new Response("Demo not found", { status: 404 });
  }

  return new Response(demo.renderedHtml, {
    status: 200,
    headers: {
      "content-type": "text/html; charset=utf-8",
      "x-robots-tag": "noindex, nofollow",
      "cache-control": "no-store",
      // Defensive: the demo is self-contained, but forbid it from being framed
      // by any third-party origin.
      "content-security-policy": "frame-ancestors 'self'",
    },
  });
}
