import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { authenticateApiToken, tokenHasScope } from "@/lib/api-auth";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const dynamic = "force-dynamic";

/**
 * GET /api/v1/servers
 * Bearer-token authenticated. Returns the caller's servers.
 *
 *   Authorization: Bearer nxe_<prefix>_<random>
 */
export async function GET(req: Request) {
  const auth = await authenticateApiToken(req);
  if (!auth.ok) {
    return NextResponse.json({ error: auth.error }, { status: auth.status, headers: NO_STORE_HEADERS });
  }

  // Enforce read scope. Legacy tokens (no scopes recorded) are READ-ONLY — they
  // satisfy this check and nothing that mutates. See `tokenHasScope` in
  // lib/api-auth.ts; a mutating endpoint must use `authorizeApiRequest`.
  if (!tokenHasScope(auth, "servers:read")) {
    return NextResponse.json(
      { error: "Token missing required scope: servers:read" },
      { status: 403, headers: NO_STORE_HEADERS }
    );
  }

  const servers = await db.server.findMany({
    where: { userId: auth.user.id },
    orderBy: { createdAt: "desc" },
    select: { id: true, name: true, status: true, ipAddress: true },
  });

  // Per-account inventory (names + IP addresses). The URL is identical for every
  // token holder, so a shared cache keyed on the URL alone would serve one
  // customer's server list to the next — `Authorization` is a request header and
  // does not vary the cache key on its own. `private` is the control that matters.
  return NextResponse.json(
    {
      servers: servers.map((s) => ({
        id: s.id,
        name: s.name,
        status: s.status,
        ip: s.ipAddress,
      })),
    },
    { headers: NO_STORE_HEADERS }
  );
